import pandas as pd
import numpy as np

df = pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)

# Parse all numeric columns: fix commas to dots, handle scientific notation
def parse_val(v):
    if pd.isna(v) or v.strip() == '':
        return np.nan
    v = v.strip().replace(',', '.')
    try:
        return float(v)
    except:
        return np.nan

numeric_cols = [c for c in df.columns if c != 'patient_id']

# Parse and get stats
for col in numeric_cols:
    vals = df[col].apply(parse_val)
    valid = vals.dropna()
    if len(valid) > 0:
        print(f"{col:40s} | min={valid.min():12.4f} | max={valid.max():12.4f} | mean={valid.mean():12.4f} | count={len(valid)}")
